      { k: 'tap', age: 12, q: 'Tap the predicate (what happens).', s: 'My little sister and I built a snow fort.', ans: [5, 6, 7, 8], why: 'Built a snow fort tells what my little sister and I did.' },
      { k: 'pick', age: 12, q: 'What is the simple subject (the main word)?', s: 'The hungry brown bear ate berries.', opts: ['bear', 'brown', 'berries'], ans: 'bear', why: 'Bear is the main word in the subject. Hungry and brown describe it.' },
      { k: 'pick', age: 12, q: 'What is the simple predicate (the main verb)?', s: 'The hungry brown bear ate berries.', opts: ['ate', 'berries', 'hungry'], ans: 'ate', why: 'Ate is the main verb. It tells what the bear did.' },
      { k: 'pick', age: 12, q: 'What is the subject?', s: 'Where did the boat go?', opts: ['the boat', 'Where', 'go'], ans: 'the boat', why: 'Turn it around: the boat did go somewhere. The boat is the subject.' }
